<template><div class="page-container operations-page"><PageHeader title="Bảng điều hành hệ thống" description="Theo dõi event pipeline, sức khỏe cấu hình và khả năng phục hồi dữ liệu." :breadcrumbs="[{label:'Điều hành'},{label:'Operations'}]"><template #actions><BaseButton variant="secondary" :loading="loading" @click="loadData">Làm mới</BaseButton></template></PageHeader>
<section class="summary-grid" aria-label="Tổng quan event"><BaseCard variant="kpi"><span>Tổng event</span><strong>{{ summary.totalEvents }}</strong><small>Trong cửa sổ quan sát</small></BaseCard><BaseCard variant="kpi"><span>Đang chờ</span><strong>{{ summary.pendingEvents }}</strong><small>Chưa được dispatch</small></BaseCard><BaseCard variant="kpi"><span>Đã dispatch</span><strong>{{ summary.dispatchedEvents }}</strong><small>Đã chuyển đến consumer</small></BaseCard><BaseCard variant="kpi"><span>Failed / dead letter</span><strong>{{ summary.failedEvents }} / {{ summary.deadLetter }}</strong><small>Cần can thiệp vận hành</small></BaseCard></section>
<EmptyState v-if="loadError" kind="error" title="Không thể tải bảng điều hành" :description="loadError"><template #actions><BaseButton variant="secondary" @click="loadData">Thử lại</BaseButton></template></EmptyState><div v-else class="dashboard-grid"><BaseCard variant="panel" class="trend-panel"><header><div><h2>Xu hướng event 24 giờ</h2><p>{{ eventTrends.length ? 'Khối lượng theo từng mốc ghi nhận.' : 'Chưa có dữ liệu xu hướng.' }}</p></div></header><LoadingSkeleton v-if="loading" variant="card" :lines="4"/><div v-else-if="eventTrends.length" class="chart" role="img" aria-label="Biểu đồ event theo thời gian"><div v-for="(bar,index) in eventTrends" :key="bar.time||index" class="bar"><span class="bar-value">{{ bar.count||0 }}</span><span class="bar-fill" :style="{height:`${Math.max(4,(Number(bar.count)||0)/maxEvents*100)}%`}"></span><small>{{ bar.time||index+1 }}</small></div></div><EmptyState v-else title="Chưa có event trend" description="Dữ liệu sẽ xuất hiện khi pipeline ghi nhận các cửa sổ đo."/></BaseCard>
<BaseCard variant="panel" class="health-panel"><header><div><h2>Sức khỏe cấu hình</h2><p>Finding được nhóm theo miền kiểm soát.</p></div></header><LoadingSkeleton v-if="loading" variant="card" :lines="4"/><EmptyState v-else-if="!configHealth.length" title="Chưa có health check" description="Không có kết quả kiểm tra cấu hình để hiển thị."/><div v-else class="health-list"><article v-for="item in configHealth" :key="item.category"><header><strong>{{ item.category }}</strong><StatusBadge :status="healthSemantic(item.status)" :label="healthLabel(item.status)" dot/></header><ul v-if="item.findings?.length"><li v-for="finding in item.findings" :key="finding.id"><StatusBadge :status="healthSemantic(finding.severity)" :label="finding.severity" size="small"/><span>{{ finding.message }}</span></li></ul><p v-else>Không có finding.</p></article></div></BaseCard></div>
<section class="backup-panel" aria-labelledby="backup-title"><header><div><h2 id="backup-title">Lần chạy backup gần đây</h2><p>Đối chiếu trạng thái, dung lượng và mục tiêu RPO/RTO.</p></div></header><DataTable :columns="backupColumns" :rows="backups" row-key="backupRunId" :loading="loading" empty-title="Chưa có lần chạy backup" empty-description="Lịch sử sẽ xuất hiện sau khi job backup thực thi."><template #cell-backupRunId="{value}">#{{value}}</template><template #cell-status="{value}"><StatusBadge :status="healthSemantic(value)" :label="value||'Không rõ'" dot/></template><template #cell-startedAtUtc="{value}">{{ formatDate(value) }}</template><template #cell-sizeBytes="{value}">{{ formatBytes(value) }}</template><template #cell-target="{row}">{{ row.targetRpoMinutes??'—' }} phút / {{ row.targetRtoMinutes??'—' }} phút</template></DataTable></section></div></template>
<script setup>import{computed,onMounted,ref}from'vue';import{enterpriseApi}from'../services/enterpriseSecurityApi';import BaseButton from'../components/ui/BaseButton.vue';import BaseCard from'../components/ui/BaseCard.vue';import DataTable from'../components/ui/DataTable.vue';import EmptyState from'../components/ui/EmptyState.vue';import LoadingSkeleton from'../components/ui/LoadingSkeleton.vue';import PageHeader from'../components/ui/PageHeader.vue';import StatusBadge from'../components/ui/StatusBadge.vue';const summary=ref({totalEvents:0,pendingEvents:0,dispatchedEvents:0,failedEvents:0,deadLetter:0}),configHealth=ref([]),eventTrends=ref([]),backups=ref([]),loading=ref(true),loadError=ref('');const backupColumns=[{key:'backupRunId',label:'ID'},{key:'profile',label:'Profile'},{key:'status',label:'Trạng thái'},{key:'startedAtUtc',label:'Bắt đầu'},{key:'sizeBytes',label:'Dung lượng'},{key:'target',label:'RPO / RTO'}];const maxEvents=computed(()=>Math.max(1,...eventTrends.value.map(item=>Number(item.count)||0)));async function loadData(){loading.value=true;loadError.value='';try{const[overview,config,trends,backup]=await Promise.all([enterpriseApi.overview(),enterpriseApi.configHealth(),enterpriseApi.getCorrelations({limit:24}),enterpriseApi.getBackupRuns({limit:10})]);const operationsOverview=Array.isArray(overview)?overview[7]?.data:overview?.data;summary.value={...summary.value,...(operationsOverview||{})};configHealth.value=Array.isArray(config.data)?config.data:[];const trendData=trends.data;eventTrends.value=Array.isArray(trendData)?trendData:Array.isArray(trendData?.items)?trendData.items:[];backups.value=Array.isArray(backup.data)?backup.data:[]}catch(error){loadError.value=error.response?.data?.message||'Không thể tải dữ liệu điều hành.';configHealth.value=[];eventTrends.value=[];backups.value=[]}finally{loading.value=false}}function healthSemantic(value){return['Blocked','Failed','Critical'].includes(value)?'critical':value==='Warning'?'warning':['Completed','Healthy','Success','OK'].includes(value)?'success':'neutral'}function healthLabel(value){return{Blocked:'Bị chặn',Failed:'Thất bại',Critical:'Nghiêm trọng',Warning:'Cảnh báo',Healthy:'Ổn định'}[value]||value}function formatDate(value){return value?new Date(value).toLocaleString('vi-VN'):'—'}function formatBytes(value){if(!value)return'—';return`${(value/1048576).toFixed(2)} MB`}onMounted(loadData)</script>
<style scoped>.operations-page{display:grid;gap:var(--space-6)}.summary-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:var(--space-4)}.summary-grid span,.summary-grid small{display:block;color:var(--text-secondary);font-size:var(--type-caption-size)}.summary-grid strong{display:block;margin-block:var(--space-2);font-size:var(--type-h2-size)}.dashboard-grid{display:grid;grid-template-columns:1.2fr 1fr;gap:var(--space-5);align-items:start}.trend-panel,.health-panel{display:grid;gap:var(--space-4)}.trend-panel h2,.health-panel h2,.backup-panel h2{font-size:var(--type-h2-size)}.trend-panel header p,.health-panel header p,.backup-panel header p{color:var(--text-muted);font-size:var(--type-body-size)}.chart{height:240px;display:flex;align-items:flex-end;gap:var(--space-2);padding:var(--space-4);border:1px solid var(--border-subtle);border-radius:var(--radius-card);background:var(--surface-subtle);overflow:auto}.bar{height:100%;min-width:28px;display:grid;grid-template-rows:auto 1fr auto;justify-items:center;align-items:end;gap:var(--space-1);flex:1}.bar-fill{width:min(100%,34px);min-height:4px;border-radius:var(--radius-control) var(--radius-control) 0 0;background:var(--interactive-primary)}.bar-value,.bar small{color:var(--text-muted);font-size:var(--type-caption-size)}.health-list{display:grid;gap:var(--space-3)}.health-list article{display:grid;gap:var(--space-2);padding:var(--space-3);border:1px solid var(--border-subtle);border-radius:var(--radius-card);background:var(--surface-subtle)}.health-list article>header{display:flex;align-items:center;justify-content:space-between;gap:var(--space-3)}.health-list ul{display:grid;gap:var(--space-2);margin:0;padding:0;list-style:none}.health-list li{display:flex;align-items:flex-start;gap:var(--space-2);font-size:var(--type-body-size)}.health-list p{color:var(--text-muted);font-size:var(--type-body-size)}.backup-panel{display:grid;gap:var(--space-4)}@media(max-width:1000px){.summary-grid{grid-template-columns:repeat(2,1fr)}.dashboard-grid{grid-template-columns:1fr}}@media(max-width:640px){.summary-grid{grid-template-columns:1fr}}</style>
